def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Empty line case: one empty field
        if i == 0 and i == len(line):
            return ['']

        # End of line
        if i == len(line):
            break

        # Parse a field
        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote: add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                # Invalid: closing quote not followed by comma or end
                                return None
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field: runs to next comma, must not contain quotes
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains double quote
                    return None
                field += line[i]
                i += 1

            # Now at comma or end of line
            if i < len(line):
                i += 1  # Skip the comma

            fields.append(field)

    return fields

